style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url("https://i.postimg.cc/4dVKm2t1/Untitled-image-4.jpg");
        background-size: cover;
        background-repeat: no-repeat;
        background-attachment: fixed;
        background-position: center center;
    }

    /* Hacemos transparentes los contenedores para que se vea el fondo */
    .container, .content, .section, .rbx-body, .rbx-page, .content-wrapper, .main-content, .game-detail-page, .navbar {
        background-color: transparent !important;
    }
}
